def _general_context_state_inputs(self, ctx, mode):
    """채택된 일반 문맥과 원문/후보의 관계를 결속한다. 탐색 완료나 NIL proof는 아니다."""
    if mode not in {"nonwork_comparison", "genre_context"} or ctx is None:
        return None
    canonical = lambda value: json.dumps(value, ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), allow_nan=False)
    try:
        post = ctx.post_data
        encoded = ctx.__dict__.get("_source_bound_nsfw_original_carrier")
        originals = ctx.__dict__.get("_final_source_original_inputs")
        comments = ctx.__dict__.get("_final_source_original_comment_refs")
        if (not isinstance(post, dict) or type(ctx.post_id) is not int
                or type(post.get("post_id")) is not int or post["post_id"] != ctx.post_id
                or not isinstance(encoded, str) or len(encoded.encode()) > 65536
                or not isinstance(originals, tuple) or comments != () or ctx.comments
                or post.get("comments_raw") or post.get("image_enrichment") or post.get("images")
                or self._has_additional_neighbor_context(post) or post.get("comment_context_lines")
                or post.get("comment_dialogue_context_lines")):
            return None
        title, blocks = post.get("title"), post.get("content_blocks")
        if (not isinstance(title, str) or not 1 <= len(title) <= 256
                or not isinstance(blocks, list) or len(blocks) > 8
                or any(not isinstance(b, dict) or b.get("type") != "text"
                    or not isinstance(b.get("text"), str) or len(b["text"]) > 1024
                    or any(b.get(k) for k in ("url", "image_url", "src")) for b in blocks)):
            return None
        live = {"post_id":ctx.post_id,"title":title,
            "content_blocks":[{"type":b["type"],"text":b["text"],"url":b.get("url") or b.get("image_url") or b.get("src")} for b in blocks],"comments":[]}
        if canonical(live) != encoded:
            return None
        expected = [{"origin":"post_title","original_index":0,"raw_path":"/title",
            "selection_key":"title","raw_text":title,"raw_value":title,
            "raw_value_type":"str","caller_disposition":"passed_to_source"}]
        expected += [{"origin":"body_line","original_index":n,"raw_path":f"/content_blocks/{n}/text",
            "selection_key":"text","raw_text":b["text"],"raw_value":b["text"],
            "raw_value_type":"str","caller_disposition":"passed_to_source"} for n,b in enumerate(blocks)]
        if canonical(originals) != canonical(expected):
            return None
        lines = [title, *(b["text"] for b in blocks)]
        if any(re.search(r'https?://|www\.|["\'“”‘’「」『』《》]|(?m:^\s*[^:：\r\n]{1,80}[:：])', line) for line in lines):
            return None
        text = " ".join(lines)
        if (self._has_memory_query_signal(text) or self._has_recommendation_request_signal(text)
                or self._has_recommendation_seeking_surface_signal(text)
                or self._collect_author_new_work_alias_surfaces(ctx)):
            return None
        kinds = (ExpertType.GATEKEEPER,ExpertType.DISCOURSE,ExpertType.DECODER,ExpertType.VERIFIER,ExpertType.ARBITER)
        roots = tuple(ctx.get_expert_output(k) for k in kinds)
        gate, disc_root, decoder, verifier, arbiter = roots
        if not isinstance(gate, dict) or not isinstance(disc_root, dict):
            return None
        disc = disc_root.get("discourse_analysis")
        entities, clues = gate.get("detected_entities"), gate.get("context_clues")
        if not all(isinstance(v, dict) for v in (disc,entities,clues)):
            return None
        if (entities.get("possible_authors") or any(clues.get(k) for k in (
                "memory_query","asks_title_identification","is_asking_recommendation","is_recommendation_request",
                "has_comment_title_answer","has_url_in_comments"))
                or disc.get("author_question_span") or disc.get("author_recommendation_span")
                or disc.get("source_bound_recommendation_request")):
            return None
        vr = verifier.get("verification_result") if isinstance(verifier, dict) else None
        fd = arbiter.get("final_decision") if isinstance(arbiter, dict) else None
        early_genre = (mode == "genre_context" and decoder is None and verifier is None and arbiter is None
            and gate.get("is_noise") is True and not entities.get("possible_characters"))
        if not early_genre:
            if (not isinstance(vr,dict) or not isinstance(fd,dict)
                    or any(v.get(k) is not False for v in (vr,fd) for k in ("is_relevant","is_novel_discussion"))
                    or self._is_verifier_failure_result(vr)):
                return None
            for value in (vr,fd):
                if any(value.get(k) for k in ("novel_identity","official_title","official_novel_title",
                        "resolved_title","heretic_url","official_url","resolved_url","author_info","recommendation_candidates")):
                    return None
            relation = vr.get("relation_judgment") or {}
            if (not isinstance(relation,dict) or relation.get("post_direct_grounding") is True
                    or relation.get("discussion_target") in {"specific_work","mixed_or_uncertain","memory_query","work"}
                    or relation.get("promotion_decision") in {"allow","publish","promote"}):
                return None
            slang = vr.get("slang_insight") or {}
            if not isinstance(slang,dict) or any(slang.get(k) for k in (
                    "canonical_work_alias","decoded_term","alias_scope","attached_entity_text","attached_entity_type")):
                return None
        if mode == "nonwork_comparison":
            parts = re.split(r"(?i:vs)",title)
            ground = (vr or {}).get("grounding_check") or {}
            if (len(parts)!=2 or any(not p.strip() or len(p.strip())>64 for p in parts)
                    or any(b["text"] not in ("","- dc official App","- dc App") for b in blocks)
                    or entities.get("possible_titles") != [title] or entities.get("possible_characters")
                    or clues.get("short_post_fast_path") is not True or clues.get("short_post_title_surface") != title
                    or not self._has_structured_high_confidence_nonwork_discourse(ctx)
                    or disc.get("target_kind") != "none" or disc.get("title_novel_terms")
                    or ground.get("anchor_found") != "title_mention" or ground.get("anchor_text") != title
                    or type(ground.get("decoder_grounded")) is not bool):
                return None
            expected_state = (False,"noise","other_quarantine","unrelated","off_topic","none","context_only")
        else:
            ground = (vr or {}).get("grounding_check")
            if not early_genre and (not isinstance(ground,dict)
                    or ground.get("decoder_grounded") is not False
                    or ground.get("anchor_found") not in (None,"","none") or ground.get("anchor_text")):
                return None
            domain_evidence = disc.get("domain_evidence")
            source_evidence = [e for e in (domain_evidence or ()) if isinstance(e,str) and len(e)>=2
                and any(e in line for line in lines)]
            if (disc.get("primary_domain") != "novel_literature" or disc.get("domain_confidence") not in {"high","max"}
                    or disc.get("intent") != "discuss_genre" or disc.get("intent_confidence") not in {"high","max"}
                    or disc.get("target_kind") not in {"genre","genre_general","trope"}
                    or gate.get("post_type") not in {"genre_discussion","trope_discussion"}
                    or len(set(source_evidence))<2
                    or not re.search(r'좋아하|주면\s*좋|공통점|차이점|클리셰|취향|장르',text)):
                return None
            # 인물은 같은 작성자 원문의 비교 예시에 있을 때만 문맥 단서로 남긴다.
            for person in entities.get("possible_characters") or ():
                if not isinstance(person,str) or not any(person in b["text"] and "처럼" in b["text"] for b in blocks):
                    return None
            expected_state = (True,"trope_discussion","genre_trope_discussion","adjacent_relevant","adjacent","none","context_only")
        if self._has_strong_verified_character_work_links(ctx):
            return None
        tokens = set(re.findall(r'[0-9A-Za-z가-힣_]{2,}',text))
        tokens.update(p.strip() for p in re.split(r'(?i:vs)',title) if p.strip())
        if any(self._resolve_known_abbreviation_surface(token) for token in tokens):
            return None
        candidate_names = []
        if decoder is not None:
            if not isinstance(decoder,dict) or decoder.get("needs_verification") is not False or decoder.get("unresolved_terms") != []:
                return None
            terms = decoder.get("decoded_terms")
            if not isinstance(terms,list) or not terms or len(terms)>32:
                return None
            for term in terms:
                if (not isinstance(term,dict) or term.get("is_author_name") is not False or term.get("author_info")
                        or not isinstance(term.get("original"),str) or not any(term["original"] in line for line in lines)):
                    return None
                best=term.get("best_match")
                if not isinstance(best,dict) or best.get("confidence") not in {"none","low"}:
                    return None
                candidate_names.append(best.get("title"))
                interpretations=term.get("interpretations")
                if not isinstance(interpretations,list) or not interpretations:
                    return None
                for value in interpretations:
                    if not isinstance(value,dict):
                        return None
                    kind=value.get("type")
                    if kind == "novel_title" and value.get("context_fit") == "low" and mode == "nonwork_comparison":
                        candidate_names.append(value.get("value"))
                    elif kind not in {"general_noun","genre_term","slang","character_name"}:
                        return None
                    elif kind == "character_name" and mode != "genre_context":
                        return None
                candidates=term.get("candidates")
                if not isinstance(candidates,list) or len(candidates)>32:
                    return None
                for item in candidates:
                    if not isinstance(item,dict) or any(item.get(k) for k in ("author","character","explicit_alias_bridge","post_direct_grounding")):
                        return None
                    candidate_names.extend(item.get(k) for k in ("title","official_title","official_novel_title"))
        fields=("search_results","fetched_page_info","suspected_titles","snippet_hints","llm_snippet_analysis")
        evidence_roots=tuple(getattr(ctx,k,None) for k in fields)
        for rows in evidence_roots[:3]:
            if rows is not None and (not isinstance(rows,(list,tuple)) or len(rows)>256):
                return None
        evidence_rows=[*(evidence_roots[0] or ()),*(evidence_roots[1] or ())]
        for item in evidence_rows:
            if not isinstance(item,dict):
                return None
            if any(item.get(k) is True for k in ("explicit_alias_bridge","post_direct_grounding","verified_character_work_link")):
                return None
            url=str(item.get("url") or "")
            if self._is_novel_platform_url(url) and self._is_novel_detail_url(url):
                # 기존 공식 상세 검사와 같은 표제 필드를 경쟁 근거로 읽는다.
                # 이것은 일반 문맥 경로의 거절 근거이며 공개 허가가 아니다.
                candidate_names.extend(item.get(k) for k in ("title", "page_title"))
                structured = item.get("structured_info")
                if isinstance(structured, dict):
                    candidate_names.extend(structured.get(k) for k in
                        ("title", "page_title", "llm_identified_title"))
        for item in [*(evidence_roots[2] or ()),*((fd or {}).get("suspected_titles") or ())]:
            if not isinstance(item,dict) or str(item.get("confidence") or "low").lower() not in {"low","none"}:
                return None
            candidate_names.extend(item.get(k) for k in ("title","official_title","official_novel_title"))
        hints=evidence_roots[3]
        if hints is not None:
            if not isinstance(hints,dict):
                return None
            for group in ("title_hints","abbreviation_hints"):
                items=hints.get(group) or []
                if not isinstance(items,list) or len(items)>256:
                    return None
                for item in items:
                    if not isinstance(item,dict) or any(item.get(k) is True for k in
                            ("explicit_alias_bridge","post_direct_grounding","verified_character_work_link")):
                        return None
                    candidate_names.extend(item.get(k) for k in ("title","full","official_title"))
        snippet=evidence_roots[4]
        if snippet is not None and (not isinstance(snippet,dict) or snippet.get("identified_title")):
            return None
        # 공식 URL의 존재와 현재 원문의 작품 관계를 구분한다. 이름의 완전한 원문 일치,
        # 명시 약칭 선언 또는 원문 관계가 있으면 이 일반 문맥 경로는 사용할 수 없다.
        author_norms=[self._normalize_match_text(line) for line in lines]
        for candidate in set(x for x in candidate_names if isinstance(x,str) and x.strip()):
            norms={self._normalize_match_text(candidate),
                self._normalize_match_text(self._normalize_title_candidate(candidate))}
            if any(norm and norm in raw for norm in norms for raw in author_norms):
                return None
            if source_bound_alias_assertion(candidate,list(tokens),evidence_rows,source_text=text):
                return None
        verdict_keys=("is_relevant","is_novel_discussion","novel_identity","official_title","official_novel_title",
            "resolved_title","heretic_url","official_url","resolved_url","author_info","recommendation_candidates","suspected_titles")
        facts={"mode":mode,"expected_state":expected_state,"source":live,"carrier":expected,
            "gate":{k:gate.get(k) for k in ("is_noise","post_type","detected_entities","context_clues")},
            "discourse":disc,"decoder":decoder,
            "verifier":{k:(vr or {}).get(k) for k in (*verdict_keys,"grounding_check","relation_judgment","slang_insight")},
            "arbiter":{k:(fd or {}).get(k) for k in verdict_keys},
            "evidence":dict(zip(fields,evidence_roots)),"primary_domain":getattr(ctx,"primary_domain",None)}
        frozen=canonical(facts)
        if len(frozen.encode())>524288:
            return None
        return {"facts":frozen,"roots":(*roots,*evidence_roots),"post":post,"originals":originals,
            "source_carrier":encoded,"mode":mode,"expected_state":expected_state}
    except (AttributeError,KeyError,TypeError,ValueError):
        return None
